static const fcn12_g_t *fcn12_find(unsigned cp) {
    int lo = 0, hi = (int)FCN12_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned m = fcn12_dir[mid].cp;
        if (m == cp) return &fcn12_dir[mid];
        if (m < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
static void fcn12_glyph(int x, int y, const fcn12_g_t *g, uint32_t fg) {
    fg = fb_map(fg);
    const unsigned char *bm = fcn12_bits + g->off;
    int gx = x + g->xo, gy = y + g->yo;
    int idx = 0;
    for (int r = 0; r < g->h; r++) {
        for (int c = 0; c < g->w; c++) {
            unsigned a = (idx & 1) ? (bm[idx >> 1] & 0xF) : (bm[idx >> 1] >> 4);
            idx++;
            if (a) fcn_blend(gx + c, gy + r, a, fg);
        }
    }
}
static int fcn12_text(int x, int y, const char *s, uint32_t fg) {
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn12_g_t *g = fcn12_find(cp);
        if (g) { fcn12_glyph(x, y, g, fg); x += g->adv; }
        else if (cp < 0x80 && cp >= ' ') { x += FCN12_PX / 2; }
        s += n;
    }
    return x;
}
